import { For, type JSX } from "solid-js";
import { LOGO_LARGE, LOGO_SMALL } from "../../features/welcome/logoData";

export interface AppLogoProps {
  /** Side in px (default 48). */
  size?: number;
  /** Use the small variant (4 levels), which stays readable at tiny sizes. Default: the large variant (6 levels). */
  small?: boolean;
}

/**
 * DeepGit mark: the tile and Git tree of `src-tauri/icons/logo.svg` / `logo-small.svg`, with its colours taken from the theme tokens.
 * The data is in `src/features/welcome/logoData.ts`, generated by `scripts/gen-logo.mjs`. Every place that shows the app icon uses this.
 *
 *   <AppLogo size={20} small />
 */
export function AppLogo(props: AppLogoProps): JSX.Element {
  const shape = () => (props.small ? LOGO_SMALL : LOGO_LARGE);
  const size = () => props.size ?? 48;
  return (
    <svg class="dg-applogo" width={size()} height={size()} viewBox="0 0 1024 1024" aria-hidden="true">
      <rect class="dg-applogo-tile" width="1024" height="1024" rx="224" ry="224" />
      <g fill="none" stroke-linecap="round">
        <For each={shape().edges}>{([d, width, colour]) => <path d={d} stroke-width={width} style={{ stroke: `var(--dg-${colour})` }} />}</For>
      </g>
      <g class="dg-applogo-ring">
        <For each={shape().nodes}>
          {([x, y, r, outline, colour]) => <circle cx={x} cy={y} r={r} stroke-width={outline} style={{ fill: `var(--dg-${colour})` }} />}
        </For>
      </g>
    </svg>
  );
}
